  "schema": "workflow-atlas.evidence-declaration.v0.1",
  "declaredAt": "2026-10-18 (authored and committed BEFORE running evidence/capture.mjs)",
  "runtime": "Node >= 18 declared; the capture records the exact version used",
  "cases": {
    "normal": {
      "command": "node bin/step-receipt-chain.mjs emit fixtures/workflow.json --out evidence/raw/normal-chain.json",
      "then": "node bin/step-receipt-chain.mjs verify evidence/raw/normal-chain.json",
      "expect": { "emitExit": 0, "receipts": 2, "s3Status": "PASS", "s4Status": "UNKNOWN", "negativeControlFailed": true, "verifyExit": 0 }
    },
    "invalid": {
      "setup": "take the emitted chain; modify chain[0].observed.status to FAIL (=> RECEIPT_MODIFIED) and reorder so the second receipt is first (=> CHAIN_BROKEN)",
      "command": "node bin/step-receipt-chain.mjs verify evidence/raw/tampered-chain.json",
      "expect": { "verifyExit": 1, "errorCodes": ["RECEIPT_MODIFIED", "CHAIN_BROKEN"] }
    },
    "insufficient": {
      "command": "node bin/step-receipt-chain.mjs emit fixtures/workflow-missing-pin.json --out evidence/raw/insufficient-chain.json",
      "expect": { "emitExit": 0, "s3Status": "UNKNOWN" },
      "note": "a missing/unusable input pin must never yield PASS (declarative, not machine-checked)"
    }
  }
}

